import React from 'react';

const Privacy = () => {
  return (
    <div className="pg" id="page-privacy">
      <div className="legal">
        <h1>Privacy Policy</h1>
        <p>Last updated: December 2024</p>

        <h2>Information We Collect</h2>
        <p>We collect information you provide directly to us, such as when you contact us, subscribe to our newsletter, or use our services.</p>

        <h2>How We Use Your Information</h2>
        <p>We use the information we collect to provide, maintain, and improve our services, communicate with you, and comply with legal obligations.</p>

        <h2>Information Sharing</h2>
        <p>We do not sell, trade, or otherwise transfer your personal information to third parties without your consent, except as described in this policy.</p>

        <h2>Data Security</h2>
        <p>We implement appropriate security measures to protect your personal information against unauthorized access, alteration, disclosure, or destruction.</p>

        <h2>Contact Us</h2>
        <p>If you have any questions about this Privacy Policy, please contact us at kottapalli.deepakvarma2005@gmail.com</p>

        <div className="ldate">Last updated: December 15, 2024</div>
      </div>
    </div>
  );
};

export default Privacy;
